{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The bucket has no account-level resource configuration preventing public ACLs or bucket policies, allowing it to become publicly exposed through later configuration changes."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is not enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "HIGH",
      "explanation": "Without versioning, dashboard objects overwritten or deleted accidentally or maliciously cannot be recovered from prior versions."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "admin_dashboard" {
  bucket = "smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  versioning_configuration {
    status = "Enabled"
  }
}
",
  "fix_summary": "Added a complete S3 Public Access Block to prevent public exposure and enabled bucket versioning to support recovery from object deletion or overwrite. Event notifications, lifecycle rules, cross-region replication, access logging, and KMS-specific encryption were not added because their necessity cannot be established from this file alone."
}
